// This file is automatically generated. Do not edit it directly.
import { createClient } from '@supabase/supabase-js';
import type { Database } from './types';

// Enforce environment variables (no hardcoded anon key)
const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL as string;
const SUPABASE_PUBLISHABLE_KEY = import.meta.env
  .VITE_SUPABASE_PUBLISHABLE_KEY as string;

if (!SUPABASE_URL || !SUPABASE_PUBLISHABLE_KEY) {
  throw new Error('[Supabase] Variáveis de ambiente ausentes: VITE_SUPABASE_URL e/ou VITE_SUPABASE_PUBLISHABLE_KEY');
}

// Import the supabase client like this:
// import { supabase } from "@/integrations/supabase/client";

/**
 * Evento global disparado quando qualquer request REST/RPC volta 401
 * (token JWT expirado/inválido). O AuthProvider escuta e decide: tenta
 * refresh e, falhando, faz signOut → tela de login. Cobre TODOS os escopos
 * (profiles, permissions, mia, lojas, telemetria) sem 401 em cascata preso.
 */
export const SESSION_UNAUTHORIZED_EVENT = 'supabase:unauthorized';

const sessionGuardFetch: typeof fetch = async (input, init) => {
  const res = await fetch(input as RequestInfo, init);
  if (res.status === 401) {
    const url =
      typeof input === 'string'
        ? input
        : input instanceof URL
          ? input.href
          : (input as Request).url;
    // Ignorar 401 do próprio endpoint de auth (login/refresh) pra evitar loop
    if (!url.includes('/auth/v1/') && typeof window !== 'undefined') {
      try {
        window.dispatchEvent(new CustomEvent(SESSION_UNAUTHORIZED_EVENT));
      } catch {
        /* ambiente sem window — ignora */
      }
    }
  }
  return res;
};

export const supabase = createClient<Database>(
  SUPABASE_URL,
  SUPABASE_PUBLISHABLE_KEY,
  {
    auth: {
      storage: localStorage,
      persistSession: true,
      autoRefreshToken: true,
    },
    // headers globais; o SDK já injeta Authorization quando logado
    global: {
      fetch: sessionGuardFetch,
      headers: {
        'x-application': 'momma-stock-insight-frontend',
        // Garantir apikey sempre presente nos requests REST
        apikey: SUPABASE_PUBLISHABLE_KEY,
      },
    },
    realtime: {
      params: {
        eventsPerSecond: 10,
      },
    },
  },
);

