/**
 * Mutation para criar uma nova denúncia anônima.
 *
 * Delega 100% para a RPC `criar_denuncia_ouvidoria` (SECURITY DEFINER, sem
 * auth.uid()). O frontend nunca insere diretamente na tabela.
 *
 * Retorna o protocolo em caso de sucesso. Em caso de ok=false, lança Error
 * com a mensagem de erro vinda do banco para exibição no toast destrutivo.
 */

import { useMutation } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import type { EnviarDenunciaInput } from '../types';

interface CriarDenunciaRpcResult {
  ok: boolean;
  protocolo?: string;
  erro?: string;
}

export function useEnviarDenuncia() {
  return useMutation({
    mutationFn: async (input: EnviarDenunciaInput): Promise<string> => {
      const { data, error } = await supabase.rpc('criar_denuncia_ouvidoria', {
        p_categoria: input.categoria,
        // O banco aceita null — mas o tipo gerado declara number obrigatório;
        // cast seguro pois a RPC SECURITY DEFINER trata null internamente.
        p_loja_id: (input.loja_id ?? null) as number,
        p_mensagem: input.mensagem,
        p_senha: input.senha,
      });
      if (error) throw new Error(error.message);

      const result = data as unknown as CriarDenunciaRpcResult;
      if (!result?.ok) {
        throw new Error(result?.erro ?? 'Não foi possível registrar a denúncia.');
      }
      if (!result.protocolo) {
        throw new Error('Protocolo não retornado pelo servidor.');
      }
      return result.protocolo;
    },
  });
}

