/**
 * Mutation para o denunciante adicionar uma mensagem ao thread via protocolo + senha.
 *
 * Nenhuma identidade é transmitida. Toda validação é feita pela RPC SECURITY DEFINER
 * `responder_protocolo_ouvidoria` que verifica o hash da senha antes de inserir.
 */

import { useMutation } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';
import type { ResponderProtocoloInput } from '../types';

interface RpcResult {
  ok: boolean;
  erro?: string;
}

export function useResponderProtocolo() {
  return useMutation({
    mutationFn: async (input: ResponderProtocoloInput): Promise<void> => {
      const { data, error } = await supabase.rpc('responder_protocolo_ouvidoria', {
        p_protocolo: input.protocolo,
        p_senha: input.senha,
        p_mensagem: input.mensagem,
      });
      if (error) throw new Error(error.message);

      const result = data as unknown as RpcResult;
      if (!result?.ok) {
        throw new Error(result?.erro ?? 'Não foi possível enviar a mensagem.');
      }
    },
  });
}

