12	import { useQuery } from '@tanstack/react-query';
13	import { supabase } from '@/integrations/supabase/client';
14	import type { DenunciaOuvidoria, MensagemThread } from '../types';
15	
16	const COLUNAS_DENUNCIA =
17	  'id, protocolo, categoria, loja_id, mensagem, status, created_at, updated_at, ultima_resposta_em';
18	const COLUNAS_MENSAGEM = 'autor, mensagem, created_at';
