20	export interface OuvidoriaDetalhe {
21	  denuncia: DenunciaOuvidoria;
22	  mensagens: MensagemThread[];
23	}
24	
25	export function useOuvidoriaDetalhe(denunciaId?: string) {
26	  return useQuery<OuvidoriaDetalhe>({
27	    queryKey: ['ouvidoria', 'detalhe', denunciaId],
28	    enabled: Boolean(denunciaId),
29	    queryFn: async () => {
30	      const [denunciaRes, mensagensRes] = await Promise.all([
31	        supabase
32	          .from('ouvidoria_denuncias' as any) // tabela tipada via schema gerado
33	          .select(COLUNAS_DENUNCIA)
34	          .eq('id', denunciaId as any)
35	          .single(),
36	        supabase
37	          .from('ouvidoria_mensagens' as any)
38	          .select(COLUNAS_MENSAGEM)
39	          .eq('denuncia_id', denunciaId as any)
40	          .order('created_at', { ascending: true }),
41	      ]);
42	
43	      if (denunciaRes.error) throw new Error(denunciaRes.error.message);
44	      if (mensagensRes.error) throw new Error(mensagensRes.error.message);
45	
46	      return {
47	        denuncia: denunciaRes.data as unknown as DenunciaOuvidoria,
48	        mensagens: (mensagensRes.data ?? []) as unknown as MensagemThread[],
