1	/**
2	 * Contador de itens não-lidos da ouvidoria para o badge em tempo real.
3	 *
4	 * CRITÉRIO DE NAO-LIDO (dois componentes somados):
5	 *  1. Denúncias com status='recebida' — ainda não abertas pelas donas.
6	 *  2. Mensagens em ouvidoria_mensagens com autor='denunciante' e
7	 *     lida_pela_ouvidoria=false — respostas do denunciante não lidas.
8	 *
9	 * A soma dos dois dá o total de atenção pendente para as donas.
10	 *
11	 * REALTIME:
12	 *  - Assina o canal Supabase 'ouvidoria_unread_realtime' em postgres_changes
13	 *    para INSERT em ouvidoria_mensagens (nova mensagem do denunciante).
14	 *  - Gate: só monta a subscription quando canView===true, evitando
15	 *    tentativas de assinatura por usuários sem acesso.
16	 *  - Cleanup do canal no unmount via return do useEffect.
17	 *
18	 * A query tem refetchInterval de 30s como fallback para mutações de status
19	 * que não são capturadas pelo evento INSERT no Realtime.
20	 */
21	
22	import { useEffect } from 'react';
23	import { useQuery, useQueryClient } from '@tanstack/react-query';
24	import { supabase } from '@/integrations/supabase/client';
25	
26	const REALTIME_CHANNEL = 'ouvidoria_unread_realtime';
27	
28	export interface OuvidoriaUnreadCounts {
29	  denunciasNaoAbertas: number;
30	  mensagensNaoLidas: number;
31	  total: number;
32	}
33	
34	export function useOuvidoriaUnreadCount(canView: boolean) {
35	  const queryClient = useQueryClient();
36	
37	  const query = useQuery<OuvidoriaUnreadCounts>({
38	    queryKey: ['ouvidoria', 'unread'],
39	    enabled: canView,
40	    refetchInterval: 30_000,
41	    staleTime: 10_000,
42	    queryFn: async (): Promise<OuvidoriaUnreadCounts> => {
43	      const [denunciasRes, mensagensRes] = await Promise.all([
44	        // Componente 1: denúncias recebidas (status='recebida' = ainda não abertas)
45	        supabase
46	          .from('ouvidoria_denuncias' as any)
47	          .select('id', { count: 'exact', head: true })
48	          .eq('status' as any, 'recebida'),
49	
50	        // Componente 2: mensagens do denunciante não lidas pelas donas
51	        supabase
52	          .from('ouvidoria_mensagens' as any)
53	          .select('id', { count: 'exact', head: true })
54	          .eq('autor' as any, 'denunciante')
55	          .eq('lida_pela_ouvidoria' as any, false),
56	      ]);
57	
58	      if (denunciasRes.error) throw new Error(denunciasRes.error.message);
59	      if (mensagensRes.error) throw new Error(mensagensRes.error.message);
60	
61	      const denunciasNaoAbertas = denunciasRes.count ?? 0;
62	      const mensagensNaoLidas = mensagensRes.count ?? 0;
63	
64	      return {
