/**
 * Contador de itens não-lidos da ouvidoria para o badge em tempo real.
 *
 * CRITÉRIO DE NAO-LIDO (dois componentes somados):
 *  1. Denúncias com status='recebida' — ainda não abertas pelas donas.
 *  2. Mensagens em ouvidoria_mensagens com autor='denunciante' e
 *     lida_pela_ouvidoria=false — respostas do denunciante não lidas.
 *
 * A soma dos dois dá o total de atenção pendente para as donas.
 *
 * REALTIME:
 *  - Assina o canal Supabase 'ouvidoria_unread_realtime' em postgres_changes
 *    para INSERT em ouvidoria_mensagens (nova mensagem do denunciante).
 *  - Gate: só monta a subscription quando canView===true, evitando
 *    tentativas de assinatura por usuários sem acesso.
 *  - Cleanup do canal no unmount via return do useEffect.
 *
 * A query tem refetchInterval de 30s como fallback para mutações de status
 * que não são capturadas pelo evento INSERT no Realtime.
 */

import { useEffect } from 'react';
import { useQuery, useQueryClient } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';

const REALTIME_CHANNEL = 'ouvidoria_unread_realtime';

export interface OuvidoriaUnreadCounts {
  denunciasNaoAbertas: number;
  mensagensNaoLidas: number;
  total: number;
}

export function useOuvidoriaUnreadCount(canView: boolean) {
  const queryClient = useQueryClient();

  const query = useQuery<OuvidoriaUnreadCounts>({
    queryKey: ['ouvidoria', 'unread'],
    enabled: canView,
    refetchInterval: 30_000,
    staleTime: 10_000,
    queryFn: async (): Promise<OuvidoriaUnreadCounts> => {
      const [denunciasRes, mensagensRes] = await Promise.all([
        // Componente 1: denúncias recebidas (status='recebida' = ainda não abertas)
        supabase
          .from('ouvidoria_denuncias' as any)
          .select('id', { count: 'exact', head: true })
          .eq('status' as any, 'recebida'),

        // Componente 2: mensagens do denunciante não lidas pelas donas
        supabase
          .from('ouvidoria_mensagens' as any)
          .select('id', { count: 'exact', head: true })
          .eq('autor' as any, 'denunciante')
          .eq('lida_pela_ouvidoria' as any, false),
      ]);

      if (denunciasRes.error) throw new Error(denunciasRes.error.message);
      if (mensagensRes.error) throw new Error(mensagensRes.error.message);

      const denunciasNaoAbertas = denunciasRes.count ?? 0;
      const mensagensNaoLidas = mensagensRes.count ?? 0;

      return {
        denunciasNaoAbertas,
        mensagensNaoLidas,
        total: denunciasNaoAbertas + mensagensNaoLidas,
      };
    },
  });

  // Subscription Realtime — só quando o usuário tem acesso
  useEffect(() => {
    if (!canView) return;

    const channel = supabase
      .channel(REALTIME_CHANNEL)
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'ouvidoria_mensagens',
        },
        () => {
          // Nova mensagem inserida — invalida o contador para refetch imediato
          queryClient.invalidateQueries({ queryKey: ['ouvidoria', 'unread'] });
        },
      )
      .subscribe();

    return () => {
      supabase.removeChannel(channel);
    };
  }, [canView, queryClient]);

  return query;
}

