/**
 * Detalhe de denúncia + thread para o painel das donas.
 * Gate via useOuvidoriaAccess. Marca como lida ao montar.
 */

import { useEffect, useRef, useState } from 'react';
import { useParams, useNavigate } from 'react-router-dom';
import {
  ArrowLeft,
  Lock,
  Send,
  Loader2,
  Shield,
  MapPin,
  Calendar,
} from 'lucide-react';
import { format, parseISO } from 'date-fns';
import { ptBR } from 'date-fns/locale';
import { toast } from 'sonner';

import { Button } from '@/shared/ui/button';
import { GlassCard } from '@/shared/ui/glass-card';
import { MommaPageLayout } from '@/shared/ui/MommaPageLayout';
import { TelemetryErrorBoundary } from '@/shared/ui/TelemetryErrorBoundary';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/shared/ui/select';

import { STATUS_OUVIDORIA } from '../lib/categorias';
import { nomeLoja } from '../lib/lojas';
import { useOuvidoriaAccess } from '../model/useOuvidoriaAccess';
import { useOuvidoriaDetalhe } from '../model/useOuvidoriaDetalhe';
import { useMarcarOuvidoriaLida } from '../model/useMarcarOuvidoriaLida';
import { useResponderOuvidoria } from '../model/useResponderOuvidoria';
import { useAtualizarStatusOuvidoria } from '../model/useAtualizarStatusOuvidoria';
import { StatusBadge } from './StatusBadge';
import { CategoriaBadge } from './CategoriaBadge';
import { MensagemBubble } from './MensagemBubble';
import type { StatusOuvidoria } from '../types';

// ---------------------------------------------------------------------------
// Skeleton
// ---------------------------------------------------------------------------

function SkeletonDetalhe() {
  return (
    <MommaPageLayout>
      <div className="p-4 md:p-6 flex flex-col gap-5 max-w-3xl mx-auto w-full">
        <div className="h-8 w-48 rounded-2xl bg-[#57715B]/5 animate-pulse" />
        <div className="h-32 rounded-2xl bg-[#57715B]/5 animate-pulse" />
        <div className="h-64 rounded-2xl bg-[#57715B]/5 animate-pulse" />
      </div>
    </MommaPageLayout>
  );
}

// ---------------------------------------------------------------------------
// Componente de detalhe (já com acesso validado)
// ---------------------------------------------------------------------------

function DetalheConteudo({ denunciaId }: { denunciaId: string }) {
  const navigate = useNavigate();
  const [respostaTexto, setRespostaTexto] = useState('');
  const marcarLidaMutation = useMarcarOuvidoriaLida();
  const responderOuvidoria = useResponderOuvidoria();
  const atualizarStatus = useAtualizarStatusOuvidoria();
  const threadEndRef = useRef<HTMLDivElement>(null);

  const { data, isLoading, refetch } = useOuvidoriaDetalhe(denunciaId);

  // Marcar como lida ao montar (idempotente — RPC não falha se já lida)
  useEffect(() => {
    if (!denunciaId) return;
    marcarLidaMutation.mutate(denunciaId);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [denunciaId]);

  // Scroll ao fim da thread quando mensagens carregam
  useEffect(() => {
    if (data?.mensagens?.length) {
      threadEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  }, [data?.mensagens?.length]);

  if (isLoading) return <SkeletonDetalhe />;

  if (!data) {
    return (
      <MommaPageLayout>
        <div className="flex flex-col items-center justify-center min-h-[60vh] gap-4 p-6 text-center">
          <Shield className="h-10 w-10 text-[#57715B]/30" />
          <p className="text-sm text-muted-foreground">Denúncia não encontrada.</p>
          <Button
            variant="ghost"
            data-mia-skip
            onClick={() => navigate('/ouvidoria')}
            className="hover:bg-[#57715B]/10 text-[#57715B] rounded-xl"
          >
            Voltar ao painel
          </Button>
        </div>
      </MommaPageLayout>
    );
  }

  const { denuncia, mensagens } = data;

  const onAlterarStatus = async (novoStatus: StatusOuvidoria) => {
    if (novoStatus === denuncia.status) return;
    try {
      await atualizarStatus.mutateAsync({ denuncia_id: denuncia.id, status: novoStatus });
      toast.success('Status atualizado');
    } catch (err) {
      toast.error((err as Error).message ?? 'Erro ao atualizar status');
    }
  };

  const onResponder = async () => {
    if (!respostaTexto.trim()) return;
    try {
      await responderOuvidoria.mutateAsync({
        denuncia_id: denuncia.id,
        mensagem: respostaTexto.trim(),
      });
      setRespostaTexto('');
      await refetch();
      toast.success('Resposta enviada');
    } catch {
      // useResponderOuvidoria já lança toast de erro internamente
    }
  };

  return (
    <MommaPageLayout>
      <div className="p-4 md:p-6 flex flex-col gap-5 max-w-3xl mx-auto w-full">
        {/* Navegação de volta */}
        <button
          type="button"
          data-mia-skip
          onClick={() => navigate('/ouvidoria')}
          className="flex items-center gap-1.5 text-sm text-muted-foreground hover:text-[#57715B] transition-colors self-start -ml-1"
        >
          <ArrowLeft className="h-4 w-4" />
          Voltar ao painel
        </button>

        {/* Cabeçalho */}
        <GlassCard className="p-5 flex flex-col gap-4">
          <div className="flex flex-wrap items-start justify-between gap-3">
            <div className="flex flex-col gap-2 min-w-0">
              <span className="font-mono text-lg font-bold text-[#57715B] break-all">
                {denuncia.protocolo}
              </span>
              <div className="flex flex-wrap items-center gap-2">
                <CategoriaBadge categoria={denuncia.categoria} />
              </div>
            </div>

            {/* Seletor de status */}
            <Select value={denuncia.status} onValueChange={onAlterarStatus}>
              <SelectTrigger data-mia-filter="ouvidoria-status-detalhe" className="bg-white/60 dark:bg-black/20 backdrop-blur-md border-[#57715B]/15 focus:ring-[#57715B]/30 rounded-xl h-9 text-sm w-40">
                <SelectValue />
              </SelectTrigger>
              <SelectContent className="bg-white/90 dark:bg-[#1A1A1A]/90 backdrop-blur-xl border-white/40 dark:border-white/10 rounded-2xl">
                {STATUS_OUVIDORIA.map((s) => (
                  <SelectItem key={s.value} value={s.value}>
                    {s.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* Meta-informações */}
          <div className="flex flex-wrap items-center gap-4 text-xs text-muted-foreground border-t border-[#57715B]/10 pt-3">
            <span className="flex items-center gap-1">
              <MapPin className="h-3.5 w-3.5" />
              {nomeLoja(denuncia.loja_id)}
            </span>
            <span className="flex items-center gap-1">
              <Calendar className="h-3.5 w-3.5" />
              {format(parseISO(denuncia.created_at), "dd/MM/yyyy 'às' HH:mm", { locale: ptBR })}
            </span>
            {denuncia.ultima_resposta_em && (
              <span className="flex items-center gap-1">
                <Send className="h-3.5 w-3.5" />
                Última resposta:{' '}
                {format(parseISO(denuncia.ultima_resposta_em), "dd/MM/yyyy 'às' HH:mm", {
                  locale: ptBR,
                })}
              </span>
            )}
          </div>
        </GlassCard>

        {/* Mensagem original */}
        <div className="flex flex-col gap-2">
          <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground px-1">
            Mensagem original
          </p>
          <GlassCard className="p-4">
            <p className="text-sm text-[#2D362E] dark:text-[#E6DCCF] whitespace-pre-wrap leading-relaxed">
              {denuncia.mensagem}
            </p>
          </GlassCard>
        </div>

        {/* Thread de conversas */}
        {mensagens.length > 0 && (
          <div className="flex flex-col gap-3">
            <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground px-1">
              Conversas
            </p>
            <div className="flex flex-col gap-4 py-2">
              {mensagens.map((msg, i) => (
                <MensagemBubble key={i} mensagem={msg} />
              ))}
              <div ref={threadEndRef} />
            </div>
          </div>
        )}

        {/* Responder */}
        <div className="flex flex-col gap-2">
          <p className="text-xs font-semibold uppercase tracking-wider text-muted-foreground px-1">
            Responder ao denunciante
          </p>
          <GlassCard className="p-4 flex flex-col gap-3">
            <div className="flex items-start gap-2 text-xs text-muted-foreground bg-[#57715B]/5 rounded-xl p-3">
              <Lock className="h-3.5 w-3.5 flex-shrink-0 mt-0.5 text-[#57715B]" />
              <span>
                A resposta é visível apenas para quem conhece o protocolo e a senha da denúncia.
                Não revele identidades.
              </span>
            </div>
            <textarea
              data-mia-field="ouvidoria-resposta"
              value={respostaTexto}
              onChange={(e) => setRespostaTexto(e.target.value)}
              rows={4}
              placeholder="Escreva sua resposta..."
              className="w-full resize-none rounded-xl bg-white/60 dark:bg-black/20 backdrop-blur-md border border-[#57715B]/15 px-3 py-2.5 text-sm text-[#2D362E] dark:text-[#E6DCCF] placeholder:text-muted-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#57715B]/30 transition-shadow"
            />
            <div className="flex justify-end">
              <Button
                type="button"
                data-mia-action="ouvidoria-responder"
                onClick={onResponder}
                disabled={!respostaTexto.trim() || responderOuvidoria.isPending}
                className="bg-[#57715B] hover:bg-[#465b49] text-white rounded-xl h-9 px-5 gap-2 text-sm"
              >
                {responderOuvidoria.isPending ? (
                  <Loader2 className="h-3.5 w-3.5 animate-spin" />
                ) : (
                  <Send className="h-3.5 w-3.5" />
                )}
                Responder
              </Button>
            </div>
          </GlassCard>
        </div>
      </div>
    </MommaPageLayout>
  );
}

// ---------------------------------------------------------------------------
// Gate de acesso + página exportada
// ---------------------------------------------------------------------------

function DetalheComGate() {
  const { id } = useParams<{ id: string }>();
  const navigate = useNavigate();
  const { canView, isLoading } = useOuvidoriaAccess();

  if (isLoading) return <SkeletonDetalhe />;

  if (!canView) {
    return (
      <MommaPageLayout>
        <div className="flex items-center justify-center min-h-[60vh] p-6">
          <GlassCard variant="premium" className="p-8 max-w-sm w-full flex flex-col items-center gap-4 text-center">
            <div className="rounded-2xl bg-[#57715B]/10 p-4">
              <Lock className="h-8 w-8 text-[#57715B]" />
            </div>
            <h2 className="text-lg font-bold text-[#2D362E] dark:text-[#E6DCCF]">
              Acesso restrito a proprietárias
            </h2>
            <p className="text-sm text-muted-foreground">
              O painel de ouvidoria é acessível apenas às proprietárias da Momma.
            </p>
            <Button
              variant="ghost"
              data-mia-skip
              onClick={() => navigate('/')}
              className="hover:bg-[#57715B]/10 text-[#57715B] rounded-xl"
            >
              Ir ao início
            </Button>
          </GlassCard>
        </div>
      </MommaPageLayout>
    );
  }

  if (!id) {
    navigate('/ouvidoria');
    return null;
  }

  return <DetalheConteudo denunciaId={id} />;
}

export default function OuvidoriaDetalhePage() {
  return (
    <TelemetryErrorBoundary moduleName="ouvidoria-detalhe">
      <DetalheComGate />
    </TelemetryErrorBoundary>
  );
}

