/**
 * Testes co-located — OuvidoriaPublica.page.tsx (canal anônimo público)
 *
 * Mocks:
 *  - useEnviarDenuncia   → mutation de envio de denúncia
 *  - useConsultarProtocolo → mutation de consulta
 *  - useResponderProtocolo → mutation de resposta do denunciante
 * A página não requer autenticação; não usa StoreContext nem useOuvidoriaAccess.
 */

import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { MemoryRouter } from 'react-router-dom';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';

// ── Mocks de model hooks ──────────────────────────────────────────────────────

vi.mock('../model/useEnviarDenuncia', () => ({
  useEnviarDenuncia: vi.fn(),
}));

vi.mock('../model/useConsultarProtocolo', () => ({
  useConsultarProtocolo: vi.fn(),
}));

vi.mock('../model/useResponderProtocolo', () => ({
  useResponderProtocolo: vi.fn(),
}));

// ── Mocks de shared UI ────────────────────────────────────────────────────────

vi.mock('@/shared/ui/select', () => ({
  Select: ({ children }: any) => <div>{children}</div>,
  SelectContent: ({ children }: any) => <div>{children}</div>,
  SelectItem: ({ children }: any) => <div>{children}</div>,
  SelectTrigger: ({ children }: any) => <div>{children}</div>,
  SelectValue: () => <span />,
}));

vi.mock('@/shared/ui/button', () => ({
  Button: ({ children, ...props }: any) => <button {...props}>{children}</button>,
}));

vi.mock('@/shared/ui/input', () => ({
  Input: (props: any) => <input {...props} />,
}));

vi.mock('@/shared/ui/label', () => ({
  Label: ({ children }: any) => <label>{children}</label>,
}));

vi.mock('@/shared/ui/tabs', () => ({
  Tabs: ({ children, value, onValueChange }: any) => (
    <div data-testid="tabs" data-value={value} onClick={() => onValueChange?.('acompanhar')}>
      {children}
    </div>
  ),
  TabsContent: ({ children, value }: any) => (
    <div data-testid={`tab-content-${value}`}>{children}</div>
  ),
  TabsList: ({ children }: any) => <div data-testid="tabs-list">{children}</div>,
  TabsTrigger: ({ children, value }: any) => (
    <button data-testid={`tab-trigger-${value}`}>{children}</button>
  ),
}));

vi.mock('@/shared/ui/glass-card', () => ({
  GlassCard: ({ children, ...props }: any) => <div {...props}>{children}</div>,
}));

vi.mock('@/shared/ui/MommaPageLayout', () => ({
  MommaPageLayout: ({ children }: any) => <div>{children}</div>,
}));

// sonner
vi.mock('sonner', () => ({
  toast: { error: vi.fn(), success: vi.fn() },
}));

// date-fns
vi.mock('date-fns', () => ({
  format: () => '16/06/2026',
  parseISO: (s: string) => new Date(s),
}));
vi.mock('date-fns/locale', () => ({ ptBR: {} }));

// ── Imports após mocks ────────────────────────────────────────────────────────

import { useEnviarDenuncia } from '../model/useEnviarDenuncia';
import { useConsultarProtocolo } from '../model/useConsultarProtocolo';
import { useResponderProtocolo } from '../model/useResponderProtocolo';
import OuvidoriaPublicaPage from './OuvidoriaPublica.page';

// ── Helpers ───────────────────────────────────────────────────────────────────

function makeQC() {
  return new QueryClient({
    defaultOptions: { queries: { retry: false, gcTime: 0 } },
  });
}

function renderPage() {
  return render(
    <QueryClientProvider client={makeQC()}>
      <MemoryRouter>
        <OuvidoriaPublicaPage />
      </MemoryRouter>
    </QueryClientProvider>,
  );
}

// ── Testes ───────────────────────────────────────────────────────────────────

describe('OuvidoriaPublicaPage — estrutura', () => {
  beforeEach(() => {
    vi.mocked(useEnviarDenuncia).mockReturnValue({
      mutateAsync: vi.fn().mockResolvedValue('OUV-20260616-TEST'),
      isPending: false,
    } as any);
    vi.mocked(useConsultarProtocolo).mockReturnValue({
      mutateAsync: vi.fn().mockResolvedValue({ ok: false }),
      isPending: false,
    } as any);
    vi.mocked(useResponderProtocolo).mockReturnValue({
      mutateAsync: vi.fn(),
      isPending: false,
    } as any);
  });

  it('renderiza o cabeçalho "Canal de Ouvidoria"', () => {
    renderPage();
    expect(screen.getByText(/Canal de Ouvidoria/i)).toBeInTheDocument();
  });

  it('renderiza aba "Fazer denúncia"', () => {
    renderPage();
    expect(screen.getByTestId('tab-trigger-denunciar')).toBeInTheDocument();
  });

  it('renderiza aba "Acompanhar"', () => {
    renderPage();
    expect(screen.getByTestId('tab-trigger-acompanhar')).toBeInTheDocument();
  });

  it('renderiza o conteúdo da aba denunciar por padrão', () => {
    renderPage();
    // O formulário de denúncia está em tab-content-denunciar
    expect(screen.getByTestId('tab-content-denunciar')).toBeInTheDocument();
  });
});

describe('OuvidoriaPublicaPage — validação de formulário', () => {
  beforeEach(() => {
    vi.mocked(useEnviarDenuncia).mockReturnValue({
      mutateAsync: vi.fn(),
      isPending: false,
    } as any);
    vi.mocked(useConsultarProtocolo).mockReturnValue({
      mutateAsync: vi.fn().mockResolvedValue({ ok: false }),
      isPending: false,
    } as any);
    vi.mocked(useResponderProtocolo).mockReturnValue({
      mutateAsync: vi.fn(),
      isPending: false,
    } as any);
  });

  it('mostra erro de validação quando mensagem é muito curta', async () => {
    renderPage();

    // Localiza o textarea da mensagem no formulário de denúncia
    const textareas = document.querySelectorAll('textarea');
    const mensagemTextarea = Array.from(textareas).find(
      (ta) => ta.getAttribute('placeholder')?.includes('Descreva'),
    );

    if (mensagemTextarea) {
      fireEvent.change(mensagemTextarea, { target: { value: 'abc' } }); // < 10 chars
    }

    // Localiza e clica no botão de submit
    const submitBtn = screen
      .getAllByRole('button')
      .find((b) => b.textContent?.includes('Enviar denúncia'));

    if (submitBtn) {
      fireEvent.click(submitBtn);
    }

    await waitFor(() => {
      // Zod dispara erro de "Mínimo de 10 caracteres"
      const erros = document.querySelectorAll('.text-red-500');
      // Com mensagem curta + sem categoria + sem senha, deve haver erros
      expect(erros.length).toBeGreaterThan(0);
    });
  });
});

