/**
 * Client Supabase SEM sessão para o canal anônimo de ouvidoria.
 *
 * Problema: o client compartilhado (@/integrations/supabase/client) injeta o
 * JWT da sessão ativa no header Authorization quando o usuário está logado.
 * Mesmo que as RPCs públicas (criar_denuncia_ouvidoria,
 * consultar_protocolo_ouvidoria, responder_protocolo_ouvidoria) não leiam
 * auth.uid(), o JWT no header é um vetor de re-identificação nos logs do
 * servidor Supabase.
 *
 * Solução: criar um client dedicado com persistSession=false que NUNCA
 * injeta o JWT, usando as mesmas URL + anon key do client principal.
 * A anon key é pública por design (exposta no bundle do frontend).
 *
 * USO: APENAS nos 3 hooks públicos do canal anônimo:
 *   - useEnviarDenuncia
 *   - useConsultarProtocolo
 *   - useResponderProtocolo
 *
 * Os hooks das donas (useOuvidoriaList, useOuvidoriaDetalhe,
 * useOuvidoriaUnreadCount, useResponderOuvidoria, useAtualizarStatusOuvidoria,
 * useMarcarOuvidoriaLida, useOuvidoriaAccess) continuam usando o client
 * compartilhado — eles precisam da sessão autenticada para RLS.
 */

import { createClient } from '@supabase/supabase-js';
import type { Database } from '@/integrations/supabase/types';

const SUPABASE_URL = import.meta.env.VITE_SUPABASE_URL as string;
const SUPABASE_ANON_KEY = import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY as string;

if (!SUPABASE_URL || !SUPABASE_ANON_KEY) {
  throw new Error(
    '[ouvidoriaAnonClient] Variáveis de ambiente ausentes: VITE_SUPABASE_URL e/ou VITE_SUPABASE_PUBLISHABLE_KEY',
  );
}

/**
 * Client sem sessão — nunca envia JWT, nunca persiste credenciais.
 * Garante anonimato real nas chamadas do canal de ouvidoria.
 */
export const ouvidoriaAnonClient = createClient<Database>(
  SUPABASE_URL,
  SUPABASE_ANON_KEY,
  {
    auth: {
      persistSession: false,
      autoRefreshToken: false,
      detectSessionInUrl: false,
    },
    global: {
      headers: {
        'x-application': 'momma-ouvidoria-anon',
        apikey: SUPABASE_ANON_KEY,
      },
    },
  },
);

